arguments.command:
perl -e '
open(F, "<", "/app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat") or die;
read(F, $buf, 4096);
printf "Magic at 0: %vd\n", substr($buf, 0, 16);
seek(F, 1024, 0);
read(F, $buf, 4);
printf "At offset 1024: %vd\n", $buf;
close F;
'

